# Check isolation of pattern pixels within bands

def count_isolated_in_band(grid, h_start, h_end, v_start, v_end, pattern_val):
    """Count isolated pattern pixels (not orthogonally connected to others)"""
    cnt = 0
    for r in range(h_start, h_end+1):
        for c in range(v_start, v_end+1):
            if grid[r][c] == pattern_val:
                # Check all 4 directions
                isolated = True
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                        if grid[nr][nc] == pattern_val:
                            isolated = False
                            break
                if isolated:
                    cnt += 1
    return cnt

